class FakePaymentGateway
  def initialize(latency: 0)
    @latency = latency
    @charges = []
  end

  attr_reader :charges

  def charge(amount_cents:, token:)
    sleep @latency if @latency.positive?
    @charges << { amount_cents: amount_cents, token: token }
    OpenStruct.new(id: "ch_#{@charges.size}", status: "succeeded")
  end
end
